#include "ui/DisplayPacer.hpp"
#include <iostream>
#include <chrono>
int main(){try{WNDCLASSW c{};c.lpfnWndProc=DefWindowProcW;c.hInstance=GetModuleHandleW(nullptr);c.lpszClassName=L"NGMVHiddenPacerTest";RegisterClassW(&c);auto h=CreateWindowW(c.lpszClassName,L"Hidden own display test",0,0,0,64,64,nullptr,nullptr,c.hInstance,nullptr);ngmv::DisplayPacer pacer;pacer.start(h,true);Sleep(100);MSG msg{};int queued=0;while(PeekMessageW(&msg,h,ngmv::DisplayPacer::Message,ngmv::DisplayPacer::Message,PM_REMOVE))queued++;if(queued!=1)throw std::runtime_error("Frame requests were not coalesced");pacer.acknowledge();int frames=0;auto start=std::chrono::steady_clock::now();while(std::chrono::steady_clock::now()-start<std::chrono::milliseconds(300)){if(PeekMessageW(&msg,h,ngmv::DisplayPacer::Message,ngmv::DisplayPacer::Message,PM_REMOVE)){frames++;pacer.acknowledge();}Sleep(1);}pacer.stop();DestroyWindow(h);if(frames<3)throw std::runtime_error("No display-paced frame stream");std::cout<<"PASS own hidden output pacing frames_300ms="<<frames<<" vblanks="<<pacer.vblanks()<<" fallback="<<pacer.fallbacks()<<" max_pending=1; no visible window/hardware presentation claim\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
